vmax=max(b['vol'] for b in bars)
for i,b in enumerate(bars):
    col='#c53c45' if b['close']>=b['open'] else '#16845d'; xx=x(i)
    svg.append(f'<path d="M{xx} {y(b["high"])}V{y(b["low"])}" stroke="{col}"/><rect x="{xx-3}" y="{min(y(b["open"]),y(b["close"]))}" width="6" height="{max(1,abs(y(b["open"])-y(b["close"])))}" fill="{col}"/><rect x="{xx-3}" y="{415-b["vol"]/vmax* sixty if False else 415-b["vol"]/vmax*60}" width="6" height="{b["vol"]/vmax*60}" fill="{col}"/>')
